# Find nSamples, nPatches where allocation size is between 1048544 and 2000000
results = []
for ns in range(0x7ffe, 1000, -1):
    for np in range(0x7ffe, 1000, -1):
        alloc = ((ns+1)*(np+1)*8) & 0xFFFFFFFF
        if 1048544 < alloc < 2000000:
            items_needed = alloc // 8 + 1
            results.append((alloc, ns, np, items_needed))
            if len(results) > 5:
                break
    if len(results) > 5:
        break
for r in results:
    print(r)
